<script setup>
import {computed} from 'vue';
const props=defineProps({model:{type:Object,required:true}});
const cnaes=computed({get:()=>props.model.secondary_cnaes?.join(', ')||'',set:v=>props.model.secondary_cnaes=v.split(/[,;\n]/).map(x=>x.trim()).filter(Boolean)});
function add(){props.model.state_registrations??=[];props.model.state_registrations.push({state:'',number:'',active:null,source:'Manual'});}
</script>
<template><div class="form-grid"><label>Natureza jurídica<input v-model="model.legal_nature"/></label><label>Situação cadastral<input v-model="model.registration_status"/></label><label>Complemento<input v-model="model.complement"/></label><label>Situação da inscrição estadual<select v-model="model.ie_status"><option value="unknown">Ausente / não informada</option><option value="not_found">Não localizada na fonte consultada</option><option value="registered">Inscrições informadas</option><option value="exempt">Contribuinte isento — confirmado pelo operador</option><option value="not_applicable">Não aplicável — confirmado pelo operador</option></select></label><label class="span-2">CNAEs secundários, separados por vírgula<input v-model="cnaes"/></label></div><div class="section-label">Inscrições estaduais por UF</div><div class="table-scroll"><table class="editable-table"><thead><tr><th>UF</th><th>Inscrição</th><th>Situação</th><th>Fonte</th><th></th></tr></thead><tbody><tr v-for="(r,i) in model.state_registrations||[]" :key="i"><td><input v-model="r.state" maxlength="2" aria-label="UF da inscrição"/></td><td><input v-model="r.number" aria-label="Número da inscrição"/></td><td><select v-model="r.active" aria-label="Situação da inscrição"><option :value="null">Não informada</option><option :value="true">Ativa</option><option :value="false">Inativa</option></select></td><td><input v-model="r.source" aria-label="Fonte da inscrição"/></td><td><button type="button" class="text-button" @click="model.state_registrations.splice(i,1)">Remover</button></td></tr></tbody></table></div><button type="button" class="text-button" @click="add">Adicionar inscrição estadual</button><p class="muted">Consulta de CNPJ não comprova regime tributário ou isenção. Uma fonte sem inscrições não significa contribuinte isento.</p><small v-if="model.lookup_date">Última consulta aplicada: {{model.lookup_source}} · {{model.lookup_date}}</small></template>
